#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "trmm.h"


/* Array initialization.
 *
 * Minor optimizations:
 *  - Use temporary restrict-qualified pointers to help the compiler
 *    with alias analysis.
 *  - Precompute 1/m and 1/n to avoid redundant divisions.
 */
static
void init_array(int m, int n,
		DATA_TYPE *alpha,
		DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j;

  *alpha = (DATA_TYPE)1.5;

  DATA_TYPE (*restrict A_)[m] = A;
  DATA_TYPE (*restrict B_)[n] = B;

  const DATA_TYPE inv_m = (DATA_TYPE)1.0 / (DATA_TYPE)m;
  const DATA_TYPE inv_n = (DATA_TYPE)1.0 / (DATA_TYPE)n;

  for (i = 0; i < m; i++) {
    for (j = 0; j < i; j++) {
      A_[i][j] = (DATA_TYPE)((i + j) % m) * inv_m;
    }
    A_[i][i] = (DATA_TYPE)1.0;
    for (j = 0; j < n; j++) {
      B_[i][j] = (DATA_TYPE)((n + (i - j)) % n) * inv_n;
    }
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j;

  DATA_TYPE (*restrict B_)[n] = B;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("B");
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
      if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, B_[i][j]);
    }
  POLYBENCH_DUMP_END("B");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Original BLAS parameters:
 *   SIDE   = 'L'
 *   UPLO   = 'L'
 *   TRANSA = 'T'
 *   DIAG   = 'U'
 * => Form  B := alpha*A**T*B.
 *    A is MxM (unit lower triangular)
 *    B is MxN
 *
 * Optimizations:
 *  - Introduce restrict-qualified local pointers for A and B to
 *    improve alias analysis.
 *  - Algebraically reorder the computation so that the scaling by
 *    'alpha' is performed once on all of B before the triangular
 *    update. This is mathematically equivalent to the original loop:
 *
 *      Original per-element result:
 *        B[i][j] = alpha * (B[i][j] + sum_{k>i} A[k][i] * B[k][j])
 *
 *      Equivalent reordered computation:
 *        1) B[i][j] <- alpha * B[i][j]         (all i,j)
 *        2) B[i][j] <- B[i][j] + sum_{k>i} A[k][i] * B[k][j]
 *
 *     In step (2), B[k][j] is already scaled by 'alpha', so the final
 *     result is:
 *        B[i][j] = alpha * B0[i][j] +
 *                  sum_{k>i} A[k][i] * alpha * B0[k][j]
 *                = alpha * (B0[i][j] + sum_{k>i} A[k][i] * B0[k][j])
 *     which matches the original semantics (up to round-off).
 *
 *  - Reorder the main loops from (i, j, k) to (i, k, j) so that the
 *    innermost loop runs over 'j', accessing contiguous elements in
 *    both destination row Bi and source row Bk. This improves cache
 *    locality and enables efficient SIMD vectorization by the
 *    compiler.
 */
static
void kernel_trmm[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

  /* Local restrict-qualified views of the 2D arrays.
   * Using VLAs here preserves the original layout while helping
   * the optimizer reason about aliasing.
   */
  DATA_TYPE (*restrict A_)[m] = A;
  DATA_TYPE (*restrict B_)[n] = B;

//BLAS parameters
//SIDE   = 'L'
//UPLO   = 'L'
//TRANSA = 'T'
//DIAG   = 'U'
// => Form  B := alpha*A**T*B.
// A is MxM
// B is MxN
#pragma scop

  /* Step 1: scale the entire B matrix by alpha.
   *
   * This hoists the multiplication by 'alpha' out of the innermost
   * loops of the original code while preserving the overall
   * computation as explained in the function header.
   */
  if (alpha != (DATA_TYPE)1.0)
  {
    for (i = 0; i < _PB_M; i++) {
      DATA_TYPE *restrict Bi = B_[i];
      for (j = 0; j < _PB_N; j++) {
        Bi[j] *= alpha;
      }
    }
  }

  /* Step 2: triangular matrix-matrix multiply using A^T.
   *
   * Loop order (i, k, j):
   *   - For fixed (i, k) we perform a SAXPY/AXPY-like update
   *       Bi[j] += Aki * Bk[j]
   *     on a full row of length N.
   *   - The innermost loop over 'j' accesses Bi and Bk contiguously
   *     in memory, greatly improving spatial locality compared to
   *     the original (i, j, k) ordering where B[k][j] was accessed
   *     with a stride of N.
   */
  for (i = 0; i < _PB_M; i++) {
    DATA_TYPE *restrict Bi = B_[i];

    for (k = i + 1; k < _PB_M; k++) {
      const DATA_TYPE Aki = A_[k][i];
      const DATA_TYPE *restrict Bk = B_[k];

      for (j = 0; j < _PB_N; j++) {
        Bi[j] += Aki * Bk[j];
      }
    }
  }

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,M,m,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (m, n, &alpha, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_trmm (m, n, alpha, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(B)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
