    for (j = 0; j < n; j++) {
	if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, B[i][j]);
    }
  POLYBENCH_DUMP_END("B");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_trmm[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

  // BLAS parameters
  // SIDE   = 'L'
  // UPLO   = 'L'
  // TRANSA = 'T'
  // DIAG   = 'U'
  // => Form  B := alpha*A**T*B.
  // A is MxM
  // B is MxN

  /* The original kernel:
   *
   *   for i in 0..M-1
   *     for j in 0..N-1
   *       for k in i+1..M-1
   *         B[i][j] += A[k][i] * B[k][j];
   *       B[i][j] *= alpha;
   *
   * For each element B[i][j], the operations are:
   *   1. Start from B_in[i][j]
   *   2. Add contributions A[k][i] * B_in[k][j] for k = i+1..M-1 (in
   *      increasing k order)
   *   3. Multiply once by alpha
   *
   * We transform the loop nest to improve data locality and
   * vectorization while preserving the *exact* per-element operation
   * order:
   *
   * - We interchange the k and j loops so that the innermost loop is
   *   over j, which is the contiguous dimension of B.  For each (i,k)
   *   pair, the inner loop becomes a DAXPY-like operation:
   *
   *       B[i][:] += A[k][i] * B[k][:]
   *
   *   This gives unit-stride accesses to both B[i][:] and B[k][:],
   *   greatly improving cache behavior and enabling efficient SIMD
   *   vectorization.
   *
   * - For each row i, we perform all k-contributions first and then
   *   scale that entire row by alpha.  For each fixed (i,j), the
   *   sequence of floating-point operations (add terms for k in
   *   ascending order, then one multiply by alpha) is identical to the
   *   original code, so results are bitwise equivalent.
   *
   * - We keep the outer i loop order unchanged, which preserves the
   *   required data dependencies on B[k][j] for k > i.
   */

#pragma scop
  for (i = 0; i < _PB_M; i++) {

    /* Accumulate contributions from rows k > i into row i:
     *   B[i][:] += A[k][i] * B[k][:]
     * For each (i,k) this is a DAXPY over the contiguous j dimension.
     */
    for (k = i + 1; k < _PB_M; k++) {
      DATA_TYPE a_ki = A[k][i];

      /* Local restricted pointers to the i-th and k-th rows of B.
       * They help the compiler reason about aliasing and generate
       * efficient, vectorized code for the inner j loop.
       * For k > i, B[i][:] and B[k][:] are disjoint in memory. */
      DATA_TYPE *restrict Bi = B[i];
      DATA_TYPE *restrict Bk = B[k];

#pragma GCC ivdep
      for (j = 0; j < _PB_N; j++) {
        Bi[j] += a_ki * Bk[j];
      }
    }

    /* Now scale the entire i-th row by alpha.
     * This is algebraically and numerically equivalent to performing
     * `B[i][j] *= alpha` inside the original j-loop, because for each
     * element (i,j) it still happens after all its k-contributions. */
    {
      DATA_TYPE *restrict Bi = B[i];

#pragma GCC ivdep
      for (j = 0; j < _PB_N; j++) {
        Bi[j] *= alpha;
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,M,m,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (m, n, &alpha, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_trmm (m, n, alpha, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(B)));

  /* Be clean. */
