    for (k = i + 1; k < _PB_M; k++) {
      const DATA_TYPE Aki = A[k][i];
      const DATA_TYPE *restrict Bk = B[k];

      for (j = 0; j < _PB_N; j++) {
        Bi[j] += Aki * Bk[j];
