     alias analysis and vectorization. */
  DATA_TYPE (*restrict A_)[m] = A;
  DATA_TYPE (*restrict B_)[n] = B;

  for (i = 0; i < m; i++) {
    DATA_TYPE *Ai = &A_[i][0];
    DATA_TYPE *Bi = &B_[i][0];

    /* Initialize strictly lower triangular part of A.
       Original formula: A[i][j] = ((i + j) % m) / m.
       The sequence (i + j) % m for j = 0..i-1 is increasing
       modulo m, so we can update it incrementally. */
    int t = i % m; /* current value of (i + j) % m */
    for (j = 0; j < i; j++) {
      Ai[j] = (DATA_TYPE)t * inv_m;
      ++t;
      if (t >= m)
        t -= m;
    }
    Ai[i] = (DATA_TYPE)1.0;

