       incrementally instead of recomputing the modulo. */
    int v = (n + i) % n; /* value for j = 0 */
    for (j = 0; j < n; j++) {
      Bi[j] = (DATA_TYPE)v * inv_n;
      --v;
      if (v < 0)
        v += n;
    }
  }
}


