  /* Original code:

       for (i = 0; i < mPB; i++)
         for (j = 0; j < nPB; j++) {
           for (k = i+1; k < mPB; k++)
             B[i][j] += A[k][i] * B[k][j];
           B[i][j] = alpha * B[i][j];
         }

     For each (i,j), this computes

       B[i][j] = alpha * ( B0[i][j] +
                           sum_{k=i+1..mPB-1} A[k][i] * B0[k][j] ),

     where B0 is the input B. The final value depends only on
     A and the original B, not on intermediate updates to B.

     The following reordering is mathematically equivalent:

       1) First accumulate the triangular product without alpha:

          for (k = 0; k < mPB; k++)
            for (i = 0; i < k; i++)
              for (j = 0; j < nPB; j++)
                B[i][j] += A[k][i] * B[k][j];

          After this stage:
            B[i][j] = B0[i][j] +
                      sum_{k=i+1..mPB-1} A[k][i] * B0[k][j].

          In this nest B[k][*] is read-only and never updated,
          so it always holds B0[k][*] when used as a source.

       2) Then scale all entries by alpha:

          for (i = 0; i < mPB; i++)
            for (j = 0; j < nPB; j++)
              B[i][j] *= alpha;

          giving exactly the same final result as the original
          kernel.

     Advantages of this schedule:

       * The innermost loops traverse the contiguous j-dimension of B,
         improving spatial locality and enabling vectorization.

       * Accesses to A use whole rows A[k][0..k-1], which are also
         contiguous in memory, instead of striding down columns.

       * All loop-carried dependences of the original algorithm are
         preserved: B[k][*] is never modified before it has been fully
         used as a source row, and scaling by alpha is postponed to the
         end, which is algebraically identical.
  */

  /* Triangular matrix-matrix product (without alpha). */
  for (k = 0; k < mPB; ++k)
  {
    /* Row k of A and B are reused for all i < k; take local
       pointers once per k for better code generation. */
    DATA_TYPE *restrict Ak = &A_[k][0];
    DATA_TYPE *restrict Bk = &B_[k][0];

    for (i = 0; i < k; ++i)
    {
      const DATA_TYPE Aki = Ak[i];
      DATA_TYPE *restrict Bi = &B_[i][0];

      /* Vectorize over contiguous j.  Each iteration writes a
         distinct B[i][j] and only reads Bk[j], so there are no
         loop-carried dependences on j. */
      #pragma GCC ivdep
      for (j = 0; j < nPB; ++j)
        Bi[j] += Aki * Bk[j];
    }
  }

  /* Final scaling by alpha: independent per element, again
     traversing the contiguous j-dimension. */
  for (i = 0; i < mPB; ++i)
  {
    DATA_TYPE *restrict Bi = &B_[i][0];
    #pragma GCC ivdep
    for (j = 0; j < nPB; ++j)
      Bi[j] *= alpha_local;
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,M,m,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (m, n, &alpha, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_trmm (m, n, alpha, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(B)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
